python3 - <<'EOF'
import re,glob,os
tbl={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|',line)
    if m: tbl[m.group(1)]=m.group(2)
if not tbl:
    print(open('draft/numerals.md').read()[:800])
print('table numerals:',sorted(tbl,key=int))
used=set()
for f in glob.glob('draft/*.md'):
    if f.endswith('numerals.md'): continue
    for n in re.findall(r'\b(\d{1,3})\b',open(f).read()):
        used.add(n)
figs={}
for f in sorted(glob.glob('figures/*.md')):
    t=open(f).read()
    body,_,nums=t.partition('## Numerals shown on this figure')
    listed=set(re.findall(r'^- (\d+)',nums,re.M))
    inbody=set(re.findall(r'\b(\d{1,3})\b',body))
    inbody={x for x in inbody if x in tbl}
    figs[f]=(listed,inbody)
    print(f,'listed',sorted(listed,key=int),'body-extra',sorted(inbody-listed,key=int),'listed-not-in-body',sorted(listed-inbody,key=int))
print('table not used in spec:',sorted(set(tbl)-used,key=int))
EOF
